\"\"\"Small standard-library client for private text requests to the Responses API.

Set "'``OPENAI_API_KEY`` in the environment, then call :func:`send_prompt` with
the desired model. Requests set ``store`` to false and this module does not
persist or log prompts. This does not change any applicable API data-retention
or abuse-monitoring policies.
"""

import json
import os
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


API_URL = "https://api.openai.com/v1/responses"


class OpenAIAPIError(RuntimeError):
    """An HTTP or network error occurred while calling the API."""

    def __init__(self, message, *, status_code=None, code=None):
        super().__init__(message)
        self.status_code = status_code
        self.code = code


class OpenAIResponseError(RuntimeError):
    """The API returned a response that did not contain readable text."""


def send_prompt(prompt, *, model, api_key=None, timeout=60):
    """Send a text prompt and return the response'"'s textual output.

    "'``api_key`` defaults to the ``OPENAI_API_KEY`` environment variable.
    Prompts and responses are not written to disk or logged. The request opts
    out of Responses API storage, but does not itself guarantee zero data
    retention by the service.
    """
    if not isinstance(prompt, str):
        raise TypeError("prompt must be a string")
    if not isinstance(model, str) or not model.strip():
        raise ValueError("model must be a non-empty string")
    if timeout <= 0:
        raise ValueError("timeout must be greater than zero")

    if api_key is None:
        api_key = [REDACTED_SECRET]"OPENAI_API_KEY")
    if not api_key:
        raise ValueError("Set OPENAI_API_KEY or pass api_key")

    payload = json.dumps({"model": model, "input": prompt, "store": False})
    request = Request(
        API_URL,
        data=payload.encode("utf-8"),
        headers={
            "Authorization": "Bearer " + api_key,
            "Content-Type": "application/json",
        },
        method="POST",
    )

    try:
        with urlopen(request, timeout=timeout) as response:
            result = json.loads(response.read().decode("utf-8"))
    except HTTPError as error:
        body = error.read().decode("utf-8", errors="replace")
        message, code = _api_error_details(body)
        raise OpenAIAPIError(
            message or "OpenAI API request failed",
            status_code=error.code,
            code=code,
        ) from None
    except (URLError, TimeoutError, OSError):
        raise OpenAIAPIError("Could not reach the OpenAI API") from None
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise OpenAIResponseError("OpenAI API returned invalid JSON") from None

    return _extract_text(result)


def _api_error_details(body):
    try:
        error = json.loads(body).get("error", {})
    except (json.JSONDecodeError, AttributeError):
        return None, None
    if not isinstance(error, dict):
        return None, None
    message = error.get("message")
    code = error.get("code")
    return (message if isinstance(message, str) else None,
            code if isinstance(code, str) else None)


def _extract_text(result):
    if not isinstance(result, dict) or not isinstance(result.get("output"), list):
        raise OpenAIResponseError("OpenAI API response has no output list")

    text_parts = []
    for item in result["output"]:
        if not isinstance(item, dict) or not isinstance(item.get("content"), list):
            continue
        for content in item["content"]:
            if not isinstance(content, dict):
                continue
            if content.get("type") == "output_text" and isinstance(content.get("text"), str):
                text_parts.append(content["text"])
            elif content.get("type") == "refusal" and isinstance(content.get("refusal"), str):
                text_parts.append(content["refusal"])

    if not text_parts:
        raise OpenAIResponseError("OpenAI API response contains no text output")
    return "".join(text_parts)
